DELETE FROM categorias WHERE nombre IN ('Adopciones','Comida','Baño e higiene','Rascadores y juego','Ropa','Paseo','Salud') AND NOT EXISTS (SELECT 1 FROM productos WHERE productos.categoria_id=categorias.id);
UPDATE productos SET nombre=REPLACE(nombre,'Juguete de prueba Postman','Adorno navideño de prueba'), descripcion='Adorno de prueba del catálogo navideño.', categoria='Adornos', categoria_id=(SELECT id FROM categorias WHERE nombre='Adornos'), imagen='assets/navidad/producto-2.png' WHERE nombre IN ('Juguete de prueba Postman 1','Juguete de prueba Postman 2');
DELETE FROM categorias WHERE nombre='Comida' AND NOT EXISTS (SELECT 1 FROM productos WHERE productos.categoria_id=categorias.id);
UPDATE productos SET imagen=REPLACE(imagen,'.svg','.png') WHERE imagen REGEXP '^assets/navidad/producto-[0-9]+[.]svg$';
COMMIT;
